create table if not exists public.billing_accounts (organization_id uuid primary key references public.organizations(id) on delete cascade,provider text not null default 'stripe',provider_customer_id text unique,billing_email text,billing_name text,billing_address jsonb not null default '{}'::jsonb,tax_ids jsonb not null default '[]'::jsonb,default_currency text not null default 'EUR',tax_country_code text,tax_exempt_status text not null default 'none',payment_terms_days integer not null default 0 check(payment_terms_days between 0 and 365),status text not null default 'active' check(status in('active','suspended','closed')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.billing_catalog_prices (id uuid primary key default gen_random_uuid(),offer_code text not null references public.commercial_offers(offer_code) on delete cascade,provider text not null default 'stripe',provider_product_id text,provider_price_id text unique,currency text not null default 'EUR',unit_amount numeric(12,2) not null check(unit_amount>=0),billing_interval text not null check(billing_interval in('month','year','one_time','usage')),price_kind text not null default 'platform' check(price_kind in('platform','agent_position','addon','usage','service')),active boolean not null default true,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.billing_subscriptions (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,provider text not null default 'stripe',provider_subscription_id text unique,provider_customer_id text,status text not null default 'incomplete' check(status in('incomplete','trialing','active','past_due','unpaid','paused','canceled','incomplete_expired')),currency text not null default 'EUR',current_period_start timestamptz,current_period_end timestamptz,cancel_at_period_end boolean not null default false,canceled_at timestamptz,trial_end timestamptz,latest_provider_invoice_id text,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.billing_subscription_items (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,subscription_id uuid not null references public.billing_subscriptions(id) on delete cascade,offer_code text references public.commercial_offers(offer_code) on delete set null,agent_id uuid references public.agents(id) on delete set null,provider_subscription_item_id text unique,provider_price_id text,item_kind text not null check(item_kind in('platform','agent_position','addon','usage','service')),quantity numeric(12,4) not null default 1 check(quantity>=0),unit_amount numeric(12,2) not null default 0 check(unit_amount>=0),currency text not null default 'EUR',active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.billing_payments (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,subscription_id uuid references public.billing_subscriptions(id) on delete set null,finance_invoice_id uuid references public.finance_invoices(id) on delete set null,provider text not null default 'stripe',provider_payment_intent_id text unique,provider_charge_id text,provider_invoice_id text,amount numeric(12,2) not null check(amount>=0),refunded_amount numeric(12,2) not null default 0 check(refunded_amount>=0),currency text not null,status text not null check(status in('pending','succeeded','failed','refunded','partially_refunded','canceled')),failure_code text,failure_message text,paid_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.billing_checkout_sessions (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,requested_by_user_id uuid references auth.users(id) on delete set null,offer_code text references public.commercial_offers(offer_code) on delete set null,provider_session_id text unique,mode text not null default 'subscription' check(mode in('subscription','payment')),status text not null default 'created' check(status in('created','open','complete','expired','failed')),success_url text,cancel_url text,expires_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.billing_webhook_events (provider text not null default 'stripe',provider_event_id text not null,event_type text not null,organization_id uuid references public.organizations(id) on delete set null,object_id text,payload jsonb not null default '{}'::jsonb,processing_status text not null default 'received' check(processing_status in('received','processing','processed','ignored','failed')),attempts integer not null default 0,last_error text,received_at timestamptz not null default now(),processed_at timestamptz,primary key(provider,provider_event_id));
create index if not exists idx_billing_subscriptions_org on public.billing_subscriptions(organization_id,status); create index if not exists idx_billing_items_org_subscription on public.billing_subscription_items(organization_id,subscription_id); create index if not exists idx_billing_payments_org_created on public.billing_payments(organization_id,created_at desc); create index if not exists idx_billing_checkout_org_created on public.billing_checkout_sessions(organization_id,created_at desc); create index if not exists idx_billing_webhooks_status on public.billing_webhook_events(processing_status,received_at);
alter table public.billing_accounts enable row level security; alter table public.billing_catalog_prices enable row level security; alter table public.billing_subscriptions enable row level security; alter table public.billing_subscription_items enable row level security; alter table public.billing_payments enable row level security; alter table public.billing_checkout_sessions enable row level security; alter table public.billing_webhook_events enable row level security;
create policy billing_accounts_member_read on public.billing_accounts for select to authenticated using(exists(select 1 from public.organization_members m where m.organization_id=billing_accounts.organization_id and m.user_id=auth.uid())); create policy billing_accounts_admin_write on public.billing_accounts for all to authenticated using(exists(select 1 from public.organization_members m where m.organization_id=billing_accounts.organization_id and m.user_id=auth.uid() and m.role in('owner','admin'))) with check(exists(select 1 from public.organization_members m where m.organization_id=billing_accounts.organization_id and m.user_id=auth.uid() and m.role in('owner','admin'))); create policy billing_catalog_authenticated_read on public.billing_catalog_prices for select to authenticated using(active=true); create policy billing_subscriptions_member_read on public.billing_subscriptions for select to authenticated using(exists(select 1 from public.organization_members m where m.organization_id=billing_subscriptions.organization_id and m.user_id=auth.uid())); create policy billing_items_member_read on public.billing_subscription_items for select to authenticated using(exists(select 1 from public.organization_members m where m.organization_id=billing_subscription_items.organization_id and m.user_id=auth.uid())); create policy billing_payments_member_read on public.billing_payments for select to authenticated using(exists(select 1 from public.organization_members m where m.organization_id=billing_payments.organization_id and m.user_id=auth.uid())); create policy billing_checkout_admin_access on public.billing_checkout_sessions for all to authenticated using(exists(select 1 from public.organization_members m where m.organization_id=billing_checkout_sessions.organization_id and m.user_id=auth.uid() and m.role in('owner','admin'))) with check(exists(select 1 from public.organization_members m where m.organization_id=billing_checkout_sessions.organization_id and m.user_id=auth.uid() and m.role in('owner','admin')));
alter table public.finance_invoices add column if not exists provider_invoice_id text; alter table public.finance_invoices add column if not exists billing_subscription_id uuid references public.billing_subscriptions(id) on delete set null; alter table public.finance_transactions add column if not exists provider_payment_id text;
comment on table public.billing_accounts is 'One isolated billing identity per RYTHM tenant organization.'; comment on table public.billing_webhook_events is 'Service-side idempotency ledger; raw payloads are not exposed to tenant clients.';